/** @type {import('tailwindcss').Config} */
// Colours are CSS variables (web/src/theme.css, generated by web/scripts/gen-theme.mjs) so light and dark mode
// share the same class names. `slate` is the warm "paper" neutral scale, `brand` the office navy, `seal` the
// certification gold.
const SHADES = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950];
const palette = (name) => Object.fromEntries(SHADES.map((s) => [s, `rgb(var(--c-${name}-${s}) / <alpha-value>)`]));

export default {
  content: ["./index.html", "./src/**/*.{ts,tsx}"],
  darkMode: "class",
  theme: {
    extend: {
      colors: {
        slate: palette("slate"), brand: palette("brand"), seal: palette("seal"),
        red: palette("red"), amber: palette("amber"), green: palette("green"), emerald: palette("emerald"),
        blue: palette("blue"), violet: palette("violet"),
        surface: "rgb(var(--c-surface) / <alpha-value>)",
        raised: "rgb(var(--c-raised) / <alpha-value>)",
        sidebar: "rgb(var(--c-sidebar) / <alpha-value>)",
        accent: { 500: "#c2185b" },
      },
      fontFamily: {
        // UI text: IBM Plex Sans for Latin, IBM Plex Sans Arabic for Arabic (one family, both scripts).
        sans: ["IBM Plex Sans", "IBM Plex Sans Arabic", "system-ui", "-apple-system", "Segoe UI", "Tahoma", "sans-serif"],
        // Titles and document text: a book serif, so pages read like the certified paper they produce.
        serif: ["IBM Plex Serif", "Noto Naskh Arabic", "Georgia", "serif"],
        mono: ["ui-monospace", "SFMono-Regular", "Menlo", "Consolas", "monospace"],
      },
      boxShadow: {
        paper: "0 1px 0 rgb(var(--c-slate-200) / 0.6), 0 1px 3px rgb(0 0 0 / 0.04), 0 8px 24px -12px rgb(0 0 0 / 0.08)",
        float: "0 12px 40px -12px rgb(0 0 0 / 0.25), 0 2px 6px rgb(0 0 0 / 0.06)",
      },
      keyframes: {
        "fade-in": { from: { opacity: "0", transform: "translateY(4px)" }, to: { opacity: "1", transform: "none" } },
        shimmer: { "0%": { backgroundPosition: "200% 0" }, "100%": { backgroundPosition: "-200% 0" } },
      },
      animation: {
        "fade-in": "fade-in 180ms ease-out both",
        shimmer: "shimmer 1.6s linear infinite",
      },
    },
  },
  plugins: [],
};
